<?php
namespace App\Ai;

class PrototypeBuilder
{
    public function generate(array $input): array
    {
        $name   = trim($input['name'] ?? '') ?: 'העסק שלי';
        $rawType = $input['type'] ?? 'business_site';
        $desc    = $input['description'] ?? '';
        $field   = $input['field'] ?? '';
        $biz     = $this->detectBiz($rawType, $name, $desc, $field);
        $persona = $this->pickPersona($biz);
        $sections = $this->buildSections($biz, $persona);
        $design   = $this->pickDesign($biz, $persona);
        return ['persona'=>$persona,'style'=>$design,'site_type'=>$biz['type_key'],'brand_name'=>$biz['name'],'score'=>90,'sections'=>$sections];
    }

    private function detectBiz(string $type, string $name, string $desc, string $field): array
    {
        $text = $type . ' ' . $desc . ' ' . $field;
        $map = [
            'מסעדה'=>'restaurant','מסעדת'=>'restaurant','אוכל'=>'restaurant','שף'=>'restaurant','מטבח'=>'restaurant','בית קפה'=>'cafe',
            'חנות'=>'ecommerce','אונליין'=>'ecommerce','משלוח'=>'ecommerce','עורך דין'=>'law_firm','עו"ד'=>'law_firm','משפט'=>'law_firm',
            'רופא'=>'clinic','מרפאה'=>'clinic','קליניקה'=>'clinic','שיניים'=>'dentist',
            'הייטק'=>'tech','תוכנה'=>'tech','טכנולוגיה'=>'tech','אפליקציה'=>'tech','מחשב'=>'tech',
            'עיצוב פנים'=>'interior','עיצוב'=>'design','מעצב'=>'design','סטודיו'=>'design','גרפי'=>'design','מיתוג'=>'design',
            'אדריכל'=>'interior','שיפוץ'=>'construction','בנייה'=>'construction','קבלן'=>'construction',
            'כושר'=>'fitness','אימון'=>'fitness','מאמן'=>'fitness','יוגה'=>'fitness','פילאטיס'=>'fitness','fitness'=>'fitness','trainer'=>'fitness','coach'=>'fitness','coaching'=>'fitness',
            'צילום'=>'photography','צלם'=>'photography','נדל"ן'=>'realestate','דירה'=>'realestate',
            'פיננסים'=>'finance','ביטוח'=>'insurance','קוסמטיקה'=>'beauty','טיפוח'=>'beauty','איפור'=>'beauty','מספרה'=>'beauty',
            'חינוך'=>'education','לימוד'=>'education','גן'=>'education','קורס'=>'education',
            'רכב'=>'auto','מוסך'=>'auto','וטרינר'=>'pet','ניקיון'=>'cleaning','ייעוץ'=>'consulting','שירות'=>'consulting','פתרונות'=>'tech','אינסטלציה'=>'plumbing','חשמל'=>'electrician','הובלות'=>'moving','הפקה'=>'events',
        ];
        $tk = 'general';
        foreach($map as $k=>$v){if(mb_strpos($text,$k)!==false){$tk=$v;break;}}
        return ['name'=>$name,'type_key'=>$tk];
    }

    private function pickPersona(array $biz): array
    {
        $p = ['restaurant'=>['יוקרתי','איכות'],'cafe'=>['חם','אווירה'],'ecommerce'=>['נועז','מכירות'],'law_firm'=>['מקצועי','אמון'],'clinic'=>['מרגיע','ביטחון'],'dentist'=>['מרגיע','ביטחון'],'tech'=>['מודרני','חדשנות'],'design'=>['יוקרתי','יצירתיות'],'interior'=>['יוקרתי','יצירתיות'],'construction'=>['מקצועי','איכות'],'fitness'=>['מרגיע','בריאות'],'photography'=>['יוקרתי','יצירתיות'],'realestate'=>['יוקרתי','איכות'],'finance'=>['מקצועי','ביטחון'],'insurance'=>['מקצועי','ביטחון'],'beauty'=>['יוקרתי','טיפוח'],'education'=>['מקצועי','ידע'],'auto'=>['מקצועי','אמינות'],'pet'=>['חם','אכפתיות'],'cleaning'=>['מקצועי','אמינות'],'consulting'=>['מקצועי','ידע'],'general'=>['מודרני','אמינות'],'plumbing'=>['מקצועי','אמינות'],'electrician'=>['מקצועי','זמינות'],'moving'=>['מקצועי','אמינות'],'events'=>['יוקרתי','יצירתיות'],'default'=>['מודרני','מקצועיות']];
        $x = $p[$biz['type_key']] ?? $p['default'];
        return ['style'=>$x[0],'emotion'=>$x[1],'target'=>'לקוחות'];
    }

    private function buildSections(array $biz, array $p): array
    {
        $s = [];
        $s[] = $this->hero($biz, $p);
        $s[] = $this->stats($biz);
        $s[] = $this->features($biz);
        if ($biz['type_key'] === 'restaurant' || $biz['type_key'] === 'cafe') { $s[] = $this->gallery($biz); }
        if (in_array($biz['type_key'], ['clinic','dentist','pet','beauty','fitness','consulting','law_firm','auto','cleaning','photography','realestate','construction','interior','insurance','finance','education'])) { $s[] = $this->appointments($biz); }
        $s[] = $this->process($biz);
        $s[] = $this->testimonials($biz);
        $s[] = $this->benefits($biz);
        $s[] = $this->problemSolution($biz);
        $s[] = $this->cta($biz, 'mid');
        $s[] = $this->pricing($biz);
        $s[] = $this->faq($biz);
        $s[] = $this->team($biz);
        $s[] = $this->cta($biz, 'final');
        $s[] = $this->contact($biz);
        $s[] = $this->footer($biz);
        return $s;
    }

