    private function slug(string $t): string { return strtolower(preg_replace('/[^a-zA-Z0-9]+/','',$t)); }
    private function fetchUnsplash(string $type): string {
        $queries = ['restaurant'=>'gourmet food dish plating','cafe'=>'coffee latte cafe','ecommerce'=>'online shop','law_firm'=>'office lawyer','clinic'=>'medical clinic','dentist'=>'dental clinic','tech'=>'technology office','design'=>'graphic design','interior'=>'interior design','construction'=>'construction building','fitness'=>'gym fitness','photography'=>'photography','realestate'=>'real estate house','finance'=>'finance office','insurance'=>'insurance','beauty'=>'beauty salon','education'=>'education school','auto'=>'auto repair car','pet'=>'pet animal','cleaning'=>'cleaning service','consulting'=>'business meeting','general'=>'business office','plumbing'=>'plumber','electrician'=>'electrician','moving'=>'moving truck','events'=>'event production'];
        $query = $queries[$type] ?? 'business office';
        $key = '5Dty3lfkHGsDpJkRRZAcE09so3hly-x1kNKI2jO2vqY';
        $url = 'https://api.unsplash.com/photos/random?query='.urlencode($query).'&client_id='.$key;
        $ctx = stream_context_create(['http'=>['timeout'=>5]]);
        $r = @file_get_contents($url, false, $ctx);
        if (!$r) return '';
        $d = json_decode($r, true);
        return $d['urls']['regular'] ?? $d['urls']['small'] ?? '';
    }

    private function gallery(array $biz): array
    {
        $dishNames = [
            ['name'=>'סלט חצילים קלויים','desc'=>'חצילים קלויים בגריל עם טחינה, סילאן וגרגירי רימון — מנה ראשונה מרעננת'],
            ['name'=>'פילה מדרום אמריקה','desc'=>'נתח בקר משובח בצריבה מושלמת — מוגש עם פירה כמהין וירקות עונתיים'],
            ['name'=>'ריזוטו פטריות כמהין','desc'=>'אורז ארבוריו במרקם קרמי — פטריות יער טריות, שמן כמהין ופרמזן'],
            ['name'=>'פירות ים בחמאת שום','desc'=>'שרימפס וקלמארי טריים מוקפצים בחמאת שום ולימון — מוגש עם לחם שאור'],
            ['name'=>'קינוח שוקולד מוס','desc'=>'מוס שוקולד בלגי עשיר עם קראמבל אגוזים — קינוח מנצח'],
            ['name'=>'קרפצ׳יו סלק ועזים','desc'=>'פרוסות דקיקות של סלק צלוי — גבינת עזים, אגוזי מלך וויניגרט בלסמי'],
        ];
        $images = $this->fetchUnsplashImages($biz['type_key'] === 'cafe' ? 'coffee latte pastry' : 'delicious food dish meal', 6);
        // Attach Hebrew dish names
        foreach ($images as $i => &$img) {
            if (isset($dishNames[$i])) {
                $img['name'] = $dishNames[$i]['name'];
                $img['desc'] = $dishNames[$i]['desc'];
            }
        }
        return ['type'=>'gallery','title'=>'המנות שלנו','subtitle'=>'חוויית טעמים בלתי נשכחת — כל מנה היא יצירת אמנות','images'=>$images];
