    private function fetchUnsplashImages(string $query, int $count = 4): array
    {
        $key = '5Dty3lfkHGsDpJkRRZAcE09so3hly-x1kNKI2jO2vqY';
        $url = 'https://api.unsplash.com/search/photos?query='.urlencode($query).'&per_page='.$count.'&client_id='.$key;
        $ctx = stream_context_create(['http'=>['timeout'=>5]]);
        $r = @file_get_contents($url, false, $ctx);
        if (!$r) return [];
        $d = json_decode($r, true);
        $images = [];
        foreach ($d['results'] ?? [] as $img) {
            $images[] = [
                'url' => $img['urls']['regular'] ?? $img['urls']['small'] ?? '',
                'thumb' => $img['urls']['thumb'] ?? '',
                'alt' => $img['alt_description'] ?? $img['description'] ?? 'תמונה',
            ];
        }
        return $images;
    }

